import { canonicalDecimal } from '../decimal.js';
import {
  validateSalesHistoryConfig,
  type SalesHistoryCustomerProductRow,
  type SalesHistoryMonthlyRow,
  type SalesHistoryReadConfig,
  monthKey,
} from '../sales-history.js';
import type { DemoDataset } from './demo-data.js';

/**
 * SYNTHETIC sales and return notes behind the fake sales-history reads (stage D). Provenance: generated by this module
 * (2026-11-11); no Sankhya capture was used. Nothing real: codes come from the demo dataset, values are invented.
 * The notes are row-level on purpose, so the fake applies the same TOP / status / date-field / window filters as the real
 * query before aggregating.
 */
export const DEMO_SALE_TOP = 7101;
export const DEMO_RETURN_TOP = 7201;
/** A TOP the demo configuration does not include (an order, not a sale). Deliberately not an installation's real TOP codes. */
export const DEMO_ORDER_TOP = 7001;
/** Fixed reference day of the fake window (the fake never reads the wall clock). */
export const DEMO_SALES_HISTORY_AS_OF = '2026-11-01';

export interface DemoSalesNoteItem {
  readonly productCode: number;
  readonly quantity: string;
  readonly gross: string;
  readonly discount: string;
}

export interface DemoSalesNote {
  readonly noteId: number;
  readonly customerCode: number;
  readonly sellerCode: number;
  readonly topCode: number;
  readonly status: string;
  /** DTNEG, `YYYY-MM-DD`. */
  readonly negotiationDate: string;
  /** DTFATUR, `YYYY-MM-DD` or `null` (not invoiced). */
  readonly billingDate: string | null;
  /** VLRNOTA. */
  readonly amount: string;
  readonly items: readonly DemoSalesNoteItem[];
}

/** 3 customers, 2 sellers, 4 products; one customer with returns only; notes outside the filters on purpose. */
export function buildDemoSalesNotes(dataset: Pick<DemoDataset, 'customers' | 'sellers' | 'products'>): readonly DemoSalesNote[] {
  const [c0, c1, c2] = dataset.customers.map((c) => c.code);
  const [s0, s1] = dataset.sellers.map((s) => s.code);
  const [p0, p1, p2, p3] = dataset.products.map((p) => p.code);
  if ([c0, c1, c2, s0, s1, p0, p1, p2, p3].some((v) => v === undefined)) throw new RangeError('demo dataset too small for the sales history');
  const item = (productCode: number | undefined, quantity: string, gross: string, discount: string): DemoSalesNoteItem => ({
    productCode: productCode as number,
    quantity,
    gross,
    discount,
  });
  const note = (
    noteId: number,
    customerCode: number | undefined,
    sellerCode: number | undefined,
    topCode: number,
    status: string,
    negotiationDate: string,
    billingDate: string | null,
    amount: string,
    items: DemoSalesNoteItem[],
  ): DemoSalesNote => ({ noteId, customerCode: customerCode as number, sellerCode: sellerCode as number, topCode, status, negotiationDate, billingDate, amount, items });
  return [
    // c0 / s0: three months of sales and a return; the last sale is negotiated in October and invoiced in November.
    note(910_001, c0, s0, DEMO_SALE_TOP, 'L', '2026-08-12', '2026-08-13', '1100.50', [item(p0, '10', '800.00', '40.00'), item(p1, '4', '240.00', '0')]),
    note(910_002, c0, s0, DEMO_SALE_TOP, 'L', '2026-09-09', '2026-09-10', '640.25', [item(p0, '6', '480.00', '24.00'), item(p2, '2', '150.00', '0')]),
    note(910_003, c0, s0, DEMO_SALE_TOP, 'L', '2026-10-31', '2026-11-02', '910.00', [item(p1, '12', '720.00', '36.00'), item(p3, '3', '200.00', '0')]),
    note(910_004, c0, s0, DEMO_RETURN_TOP, 'L', '2026-10-15', '2026-10-15', '120.00', [item(p0, '1', '80.00', '0')]),
    // c0 also bought through the other seller in September.
    note(910_005, c0, s1, DEMO_SALE_TOP, 'L', '2026-09-20', '2026-09-21', '300.10', [item(p3, '5', '285.00', '0')]),
    // c1 / s1: sales over the year, plus notes the filters must leave out.
    note(910_006, c1, s1, DEMO_SALE_TOP, 'L', '2025-12-05', '2025-12-06', '505.00', [item(p2, '7', '500.00', '10.00')]),
    note(910_007, c1, s1, DEMO_SALE_TOP, 'L', '2026-03-18', '2026-03-19', '730.75', [item(p2, '9', '700.00', '0'), item(p0, '1', '30.00', '0')]),
    note(910_008, c1, s1, DEMO_SALE_TOP, 'L', '2026-09-02', '2026-09-03', '260.00', [item(p1, '4', '260.00', '0')]),
    note(910_009, c1, s1, DEMO_SALE_TOP, 'P', '2026-09-04', null, '999.99', [item(p0, '9', '999.99', '0')]),
    note(910_010, c1, s1, DEMO_ORDER_TOP, 'L', '2026-09-05', null, '888.88', [item(p1, '8', '888.88', '0')]),
    note(910_011, c1, s1, DEMO_SALE_TOP, 'L', '2025-06-10', '2025-06-11', '777.77', [item(p3, '7', '777.77', '0')]),
    // c2: returns only.
    note(910_012, c2, s0, DEMO_RETURN_TOP, 'L', '2026-05-07', '2026-05-07', '90.00', [item(p1, '2', '90.00', '0')]),
    note(910_013, c2, s0, DEMO_RETURN_TOP, 'L', '2026-06-11', '2026-06-12', '45.50', [item(p1, '1', '45.50', '0'), item(p2, '1', '5.00', '0')]),
  ];
}

// ---- exact decimal arithmetic (scale 6) ---------------------------------------------------------

const SCALE = 6;
function toUnits(text: string): bigint {
  const [whole = '0', fraction = ''] = text.split('.');
  return BigInt(whole) * 10n ** BigInt(SCALE) + BigInt(fraction.padEnd(SCALE, '0'));
}
function fromUnits(units: bigint): string {
  const whole = units / 10n ** BigInt(SCALE);
  const fraction = (units % 10n ** BigInt(SCALE)).toString().padStart(SCALE, '0');
  const canonical = canonicalDecimal(`${whole}.${fraction}`);
  if (canonical === null) throw new RangeError('amount out of range');
  return canonical;
}

function selectNotes(notes: readonly DemoSalesNote[], config: SalesHistoryReadConfig) {
  const validated = validateSalesHistoryConfig(
    { ...config, asOf: config.asOf ?? DEMO_SALES_HISTORY_AS_OF },
    `${DEMO_SALES_HISTORY_AS_OF}T00:00:00.000Z`,
  );
  const dateOf = (n: DemoSalesNote) => (validated.dateField === 'DTNEG' ? n.negotiationDate : n.billingDate);
  const selected = notes.filter((n) => {
    const date = dateOf(n);
    return (
      validated.statusCodes.includes(n.status) &&
      validated.topCodes.includes(n.topCode) &&
      date !== null &&
      date >= validated.since
    );
  });
  return { selected, dateOf };
}

function compareArrays(a: readonly number[], b: readonly number[]): number {
  for (let i = 0; i < a.length; i += 1) {
    const d = (a[i] ?? 0) - (b[i] ?? 0);
    if (d !== 0) return d;
  }
  return 0;
}

export function demoSalesHistoryMonthly(notes: readonly DemoSalesNote[], config: SalesHistoryReadConfig): SalesHistoryMonthlyRow[] {
  const { selected, dateOf } = selectNotes(notes, config);
  const groups = new Map<string, { row: Omit<SalesHistoryMonthlyRow, 'totalAmount'>; total: bigint }>();
  for (const n of selected) {
    const month = (dateOf(n) as string).slice(0, 7);
    const key = `${n.customerCode}|${n.sellerCode}|${month}|${n.topCode}`;
    const group = groups.get(key) ?? {
      row: { customerCode: n.customerCode, sellerCode: n.sellerCode, month, topCode: n.topCode, noteCount: 0 },
      total: 0n,
    };
    groups.set(key, { row: { ...group.row, noteCount: group.row.noteCount + 1 }, total: group.total + toUnits(n.amount) });
  }
  return [...groups.values()]
    .map(({ row, total }) => ({ ...row, totalAmount: fromUnits(total) }))
    .sort((a, b) =>
      compareArrays([a.customerCode, a.sellerCode, monthKey(a.month), a.topCode], [b.customerCode, b.sellerCode, monthKey(b.month), b.topCode]),
    );
}

export function demoSalesHistoryCustomerProduct(
  notes: readonly DemoSalesNote[],
  config: SalesHistoryReadConfig,
): SalesHistoryCustomerProductRow[] {
  const { selected, dateOf } = selectNotes(notes, config);
  const groups = new Map<string, { customerCode: number; productCode: number; topCode: number; notes: Set<number>; quantity: bigint; net: bigint; last: string }>();
  for (const n of selected) {
    for (const i of n.items) {
      const key = `${n.customerCode}|${i.productCode}|${n.topCode}`;
      const date = dateOf(n) as string;
      const g = groups.get(key) ?? { customerCode: n.customerCode, productCode: i.productCode, topCode: n.topCode, notes: new Set<number>(), quantity: 0n, net: 0n, last: date };
      g.notes.add(n.noteId);
      g.quantity += toUnits(i.quantity);
      g.net += toUnits(i.gross) - toUnits(i.discount);
      if (date > g.last) g.last = date;
      groups.set(key, g);
    }
  }
  return [...groups.values()]
    .map(
      (g): SalesHistoryCustomerProductRow => ({
        customerCode: g.customerCode,
        productCode: g.productCode,
        topCode: g.topCode,
        noteCount: g.notes.size,
        quantity: fromUnits(g.quantity),
        netAmount: fromUnits(g.net),
        lastSaleDate: g.last,
      }),
    )
    .sort((a, b) => compareArrays([a.customerCode, a.productCode, a.topCode], [b.customerCode, b.productCode, b.topCode]));
}
